<template>
  <section class="discovery-hub">
    <header class="page-header">
      <div><p class="eyebrow">{{ eyebrow }}</p><h1>{{ title }}</h1><p class="subtitle">{{ subtitle }}</p></div>
      <div class="header-actions"><el-button v-if="mode !== 'bookshelf'" @click="router.push('/insights')">查看社媒洞察</el-button><el-button type="primary" @click="primaryAction">{{ primaryLabel }}</el-button></div>
    </header>

    <el-alert v-if="mode === 'hot-topics'" type="info" :closable="false" show-icon class="notice">当前热点来自本工作空间已有研究和内容信号；接入外部平台连接器后，才会增加实时平台热榜。</el-alert>

    <div class="stats-row"><div><span>研究信号</span><strong>{{ projects.length }}</strong><small>问题与来源</small></div><div><span>内容选题</span><strong>{{ topics.length }}</strong><small>可继续创作</small></div><div><span>知识卡片</span><strong>{{ knowledgeItems.length }}</strong><small>已沉淀内容</small></div><div><span>知识库</span><strong>{{ datasets.length }}</strong><small>可检索资料</small></div></div>

    <el-card v-if="mode === 'brainstorm'" shadow="never" class="idea-card"><template #header><div class="card-heading"><div><span class="section-kicker">BRAINSTORM DESK</span><h2>把一个模糊想法变成选题</h2></div></div></template><div class="idea-form"><el-input v-model="ideaTitle" placeholder="例如：为什么个人工作台总是用不起来？" @keyup.enter="createIdea" /><el-input v-model="ideaBrief" type="textarea" :rows="3" placeholder="补充背景、目标用户或你想验证的问题（可选）" /><div class="form-actions"><span>创建后会进入内容中心选题池</span><el-button type="primary" :loading="creating" @click="createIdea">加入选题池</el-button></div></div></el-card>

    <el-card shadow="never" class="filter-card"><div class="filter-row"><el-input v-model="keyword" clearable placeholder="搜索标题、问题、知识或知识库" /><el-select v-model="statusFilter" clearable placeholder="全部状态"><el-option label="已完成" value="completed" /><el-option label="已审核" value="approved" /><el-option label="可运行" value="active" /></el-select><el-button @click="resetFilters">重置</el-button></div></el-card>

    <template v-if="mode === 'hot-topics'">
      <div class="hot-summary"><div><span>今日新增信号</span><strong>{{ hotTodayCount }}</strong><small>按本地创建时间计算</small></div><div><span>可验证问题</span><strong>{{ hotResearchCount }}</strong><small>已有研究或问题描述</small></div><div><span>内容信号</span><strong>{{ hotTopicCount }}</strong><small>可继续进入选题池</small></div><div><span>内部证据</span><strong>{{ hotEvidenceCount }}</strong><small>样本、问题与状态</small></div></div>
      <el-card shadow="never" class="hot-filter-card"><div class="hot-filter-heading"><div><span class="section-kicker">LOCAL SIGNAL FILTER</span><h2>先看来源，再决定是否跟进</h2></div><span class="hot-updated">{{ hotSignals.length }} 条本地信号</span></div><div class="hot-filter-row"><el-radio-group v-model="hotSourceFilter"><el-radio-button label="all">全部来源</el-radio-button><el-radio-button label="research">研究信号</el-radio-button><el-radio-button label="topic">内容信号</el-radio-button></el-radio-group><el-select v-model="hotSort" size="small"><el-option label="最近更新" value="recent" /><el-option label="优先验证" value="priority" /></el-select></div></el-card>
      <div class="hot-topic-grid"><article v-for="item in hotSignals" :key="`${item.kind}-${item.id}`" class="hot-topic-card"><div class="card-top"><div class="tag-group"><el-tag size="small" :type="item.kind === 'research' ? 'primary' : 'warning'">{{ item.kind === 'research' ? '研究信号' : '内容信号' }}</el-tag><el-tag size="small" effect="plain" :type="priorityType(item)">{{ priorityLabel(item) }}</el-tag></div><span>{{ formatDate(item.created_at) }}</span></div><h2>{{ item.title }}</h2><p>{{ item.description }}</p><div class="hot-evidence"><span>{{ item.meta }}</span><span>{{ statusLabel(item.status) }}</span></div><div class="card-footer"><span>{{ item.kind === 'research' ? '来源：研究项目' : '来源：内容选题' }}</span><el-button link type="primary" @click="openSignal(item)">{{ item.kind === 'research' ? '验证问题' : '进入选题池' }} <el-icon><ArrowRight /></el-icon></el-button></div></article><el-empty v-if="!hotSignals.length" description="暂无匹配的本地热点信号" :image-size="72" /></div>
    </template>

    <div v-if="mode === 'bookshelf'" class="book-grid"><article v-for="dataset in filteredDatasets" :key="dataset.id" class="book-card" @click="router.push(`/datasets/${dataset.id}`)"><div class="book-spine" /><div class="book-body"><span class="section-kicker">KNOWLEDGE BOOK</span><h2>{{ dataset.name }}</h2><p>{{ dataset.description || '暂无知识库描述' }}</p><div><strong>{{ dataset.document_count || 0 }}</strong><small>篇文档</small><el-icon><ArrowRight /></el-icon></div></div></article><el-empty v-if="!filteredDatasets.length" description="还没有匹配的知识库" :image-size="72" /></div>

    <div v-if="mode === 'inspiration'" class="inspiration-grid"><article v-for="item in filteredKnowledge" :key="item.id" class="inspiration-card"><div class="card-top"><el-tag size="small" :type="item.review_status === 'approved' ? 'success' : 'info'">{{ reviewLabel(item.review_status) }}</el-tag><span>{{ Math.round(item.confidence * 100) }}% 置信度</span></div><h2>{{ item.title }}</h2><p>{{ item.definition }}</p><div class="card-footer"><span>{{ item.evidence?.length || 0 }} 条证据 · {{ formatDate(item.updated_at) }}</span><el-button link type="primary" @click="router.push('/knowledge')">打开知识中心 <el-icon><ArrowRight /></el-icon></el-button></div></article><el-empty v-if="!filteredKnowledge.length" description="还没有可用灵感，可先从素材沉淀知识" :image-size="72" /></div>

    <div v-if="mode !== 'hot-topics' && mode !== 'bookshelf' && mode !== 'inspiration'" class="signal-grid"><article v-for="item in filteredSignals" :key="item.id" class="signal-card"><div class="card-top"><el-tag size="small" :type="item.kind === 'research' ? 'primary' : 'warning'">{{ item.kind === 'research' ? '研究信号' : '内容信号' }}</el-tag><span>{{ formatDate(item.created_at) }}</span></div><h2>{{ item.title }}</h2><p>{{ item.description }}</p><div class="card-footer"><span>{{ item.meta }}</span><el-button link type="primary" @click="openSignal(item)">{{ item.kind === 'research' ? '打开研究' : '进入内容' }} <el-icon><ArrowRight /></el-icon></el-button></div></article><el-empty v-if="!filteredSignals.length" description="暂无匹配信号" :image-size="72" /></div>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowRight } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { getDatasets } from '@/api/dataset'
import { knowledgeApi } from '@/api/knowledge'
import { researchApi } from '@/api/research'
import { contentApi } from '@/api/content'
import { useWorkspaceStore } from '@/stores/workspace'
import type { Dataset } from '@/types/dataset'
import type { KnowledgeItem } from '@/types/knowledge'
import type { ResearchProject } from '@/types/research'
import type { ContentTopic } from '@/types/content'

const route = useRoute(); const router = useRouter(); const workspaceStore = useWorkspaceStore(); const mode = computed(() => route.path.includes('hot-topics') ? 'hot-topics' : route.path.includes('inspiration') ? 'inspiration' : route.path.includes('bookshelf') ? 'bookshelf' : 'brainstorm')
const title = computed(() => ({ brainstorm: 'Brainstorm', 'hot-topics': '每日热点', inspiration: '灵感库', bookshelf: '书架' } as Record<string,string>)[mode.value]); const eyebrow = computed(() => ({ brainstorm: 'IDEA DESK · BRAINSTORM', 'hot-topics': 'DAILY SIGNALS · LOCAL EVIDENCE', inspiration: 'INSPIRATION VAULT · KNOWLEDGE', bookshelf: 'BOOKSHELF · KNOWLEDGE BASES' } as Record<string,string>)[mode.value]); const subtitle = computed(() => ({ brainstorm: '记录还没有答案的想法，让研究、内容和知识逐步把它变成可执行的方向。', 'hot-topics': '把今天值得关注的问题从研究和内容信号里筛出来，保持来源可核对。', inspiration: '从已审核知识和证据里发现可复用的观点，避免灵感只停留在收藏。', bookshelf: '用书架方式浏览团队知识库，每本资料都能继续检索、问答和沉淀。' } as Record<string,string>)[mode.value]); const primaryLabel = computed(() => mode.value === 'bookshelf' ? '新建知识库' : mode.value === 'brainstorm' ? '快速创建选题' : '进入研究洞察')
const projects = ref<ResearchProject[]>([]); const topics = ref<ContentTopic[]>([]); const knowledgeItems = ref<KnowledgeItem[]>([]); const datasets = ref<Dataset[]>([]); const keyword = ref(''); const statusFilter = ref(''); const hotSourceFilter = ref('all'); const hotSort = ref('recent'); const ideaTitle = ref(''); const ideaBrief = ref(''); const creating = ref(false)
const filteredDatasets = computed(() => datasets.value.filter(item => !keyword.value || `${item.name} ${item.description}`.toLowerCase().includes(keyword.value.toLowerCase())))
const filteredKnowledge = computed(() => knowledgeItems.value.filter(item => { const text = `${item.title} ${item.definition}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!statusFilter.value || item.review_status === statusFilter.value) }))
const filteredSignals = computed(() => signals.value.filter(item => { const text = `${item.title} ${item.description}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!statusFilter.value || item.status === statusFilter.value) }))
const signals = computed(() => [...projects.value.map(item => ({ id: item.id, kind: 'research', title: item.name, description: item.description || item.questions?.[0]?.question || '暂无研究描述', meta: `${item.sample_count || 0} 个样本 · ${item.questions?.length || 0} 个问题`, status: item.status, created_at: item.created_at })), ...topics.value.map(item => ({ id: item.id, kind: 'topic', title: item.title, description: item.brief || '暂无选题说明', meta: item.status || 'idea', status: item.status, created_at: item.created_at }))])
const hotSignals = computed(() => signals.value.filter(item => { const text = `${item.title} ${item.description}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!statusFilter.value || item.status === statusFilter.value) && (hotSourceFilter.value === 'all' || item.kind === hotSourceFilter.value) }).sort((a, b) => hotSort.value === 'priority' ? signalPriority(b) - signalPriority(a) : new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime()))
const hotTodayCount = computed(() => signals.value.filter(item => item.created_at && new Date(item.created_at).toDateString() === new Date().toDateString()).length)
const hotResearchCount = computed(() => signals.value.filter(item => item.kind === 'research').length)
const hotTopicCount = computed(() => signals.value.filter(item => item.kind === 'topic').length)
const hotEvidenceCount = computed(() => projects.value.reduce((sum, item) => sum + (item.sample_count || 0) + (item.questions?.length || 0), 0))
function formatDate(value?: string) { return value ? new Date(value).toLocaleDateString('zh-CN') : '最近更新' }; function reviewLabel(value: string) { return ({ approved: '已审核', draft: '草稿', rejected: '已驳回' } as Record<string,string>)[value] || value }; function statusLabel(value?: string) { return ({ completed: '已完成', active: '进行中', approved: '已审核', idea: '待验证', draft: '草稿' } as Record<string,string>)[value || ''] || value || '待确认' }; function signalPriority(item: { kind: string; status?: string; created_at?: string }) { const age = item.created_at ? (Date.now() - new Date(item.created_at).getTime()) / 86400000 : 99; return (item.kind === 'research' ? 2 : 1) + (['completed', 'approved'].includes(item.status || '') ? 2 : 1) + (age <= 3 ? 1 : 0) }; function priorityLabel(item: { kind: string; status?: string; created_at?: string }) { const score = signalPriority(item); return score >= 5 ? '高优先级' : score >= 3 ? '值得验证' : '可继续观察' }; function priorityType(item: { kind: string; status?: string; created_at?: string }) { const score = signalPriority(item); return score >= 5 ? 'danger' : score >= 3 ? 'warning' : 'info' }; function resetFilters() { keyword.value = ''; statusFilter.value = ''; hotSourceFilter.value = 'all'; hotSort.value = 'recent' }
function primaryAction() { if (mode.value === 'bookshelf') router.push('/datasets/create'); else if (mode.value === 'brainstorm') document.querySelector('.idea-card')?.scrollIntoView({ behavior: 'smooth' }); else router.push('/research') }
function openSignal(item: { kind: string; id: string }) { router.push(item.kind === 'research' ? `/insights/${item.id}` : '/content') }
async function createIdea() { const workspaceId = workspaceStore.currentWorkspaceId; if (!workspaceId || !ideaTitle.value.trim()) return ElMessage.warning('请输入一个想法或选题标题'); creating.value = true; try { await contentApi.createTopic({ workspace_id: workspaceId, title: ideaTitle.value.trim(), brief: ideaBrief.value.trim() || undefined }); ideaTitle.value = ''; ideaBrief.value = ''; ElMessage.success('已加入内容选题池'); await load() } catch (error) { ElMessage.error(error instanceof Error ? error.message : '选题创建失败') } finally { creating.value = false } }
async function load() { const workspaceId = workspaceStore.currentWorkspaceId; if (!workspaceId) return; const results = await Promise.allSettled([researchApi.listProjects(workspaceId), contentApi.listTopics(workspaceId), knowledgeApi.list(workspaceId), getDatasets({ workspace_id: workspaceId, page: 1, page_size: 100 })]); const [projectResult, topicResult, knowledgeResult, datasetResult] = results; projects.value = projectResult.status === 'fulfilled' ? projectResult.value.items || [] : []; topics.value = topicResult.status === 'fulfilled' ? topicResult.value.items || [] : []; knowledgeItems.value = knowledgeResult.status === 'fulfilled' ? knowledgeResult.value.items || [] : []; if (datasetResult.status === 'fulfilled') { const raw = Array.isArray(datasetResult.value) ? datasetResult.value : datasetResult.value?.items || datasetResult.value?.data?.items || []; datasets.value = raw as Dataset[] } else datasets.value = []; if (results.some(result => result.status === 'rejected')) ElMessage.warning('部分发现数据暂时不可用，已保留可加载内容') }
onMounted(async () => { await workspaceStore.fetchCurrentWorkspace(); await load() })
</script>

<style scoped lang="scss">
.discovery-hub{max-width:1440px;margin:0 auto}.page-header{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;margin-bottom:22px}.header-actions{display:flex;gap:10px;padding-top:18px}.eyebrow,.section-kicker{color:var(--el-color-primary);font-size:11px;font-weight:800;letter-spacing:.16em}.eyebrow{margin:0 0 8px}h1{margin:0 0 8px;font-family:Georgia,'Times New Roman',serif;font-size:clamp(32px,4vw,48px);letter-spacing:-.045em}.subtitle{max-width:720px;margin:0;color:var(--el-text-color-secondary);line-height:1.75}.notice{margin-bottom:18px;border:1px solid rgba(112,74,198,.14);border-radius:14px;background:#faf8ff}.stats-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.stats-row>div,.idea-card,.filter-card,.signal-card,.inspiration-card,.book-card{border:1px solid rgba(112,74,198,.13);border-radius:18px;background:linear-gradient(145deg,rgba(255,255,255,.96),rgba(249,247,255,.9));box-shadow:0 12px 30px rgba(79,51,133,.05)}.stats-row>div{display:flex;flex-direction:column;gap:5px;padding:17px 20px}.stats-row span,.stats-row small,.card-top span,.card-footer span{color:var(--el-text-color-secondary)}.stats-row strong{font-family:Georgia,'Times New Roman',serif;font-size:30px;color:var(--el-color-primary)}.idea-card{margin-bottom:18px}.idea-card :deep(.el-card__body){padding:20px}.card-heading{display:flex;justify-content:space-between;align-items:flex-start}.card-heading h2{margin:5px 0 0;font-size:20px}.idea-form{display:grid;gap:12px}.form-actions{display:flex;align-items:center;justify-content:space-between;color:var(--el-text-color-secondary);font-size:12px}.filter-card{margin-bottom:18px}.filter-card :deep(.el-card__body){padding:14px}.filter-row{display:flex;gap:10px}.filter-row .el-input{flex:1}.filter-row .el-select{width:170px}.signal-grid,.inspiration-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.signal-card,.inspiration-card{padding:18px}.card-top,.card-footer{display:flex;justify-content:space-between;align-items:center;gap:10px}.signal-card h2,.inspiration-card h2{margin:14px 0 7px;font-size:18px}.signal-card p,.inspiration-card p{min-height:46px;margin:0 0 16px;color:var(--el-text-color-secondary);line-height:1.65}.card-footer{padding-top:12px;border-top:1px solid rgba(112,74,198,.08);font-size:12px}.book-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.book-card{display:flex;min-height:210px;overflow:hidden;cursor:pointer;transition:transform .2s,border-color .2s}.book-card:hover{transform:translateY(-3px);border-color:rgba(112,74,198,.35)}.book-spine{width:14px;background:linear-gradient(#8c63da,#5e37af)}.book-body{display:flex;flex:1;flex-direction:column;padding:22px}.book-body h2{margin:12px 0 8px;font-size:21px}.book-body p{flex:1;margin:0;color:var(--el-text-color-secondary);line-height:1.6}.book-body>div{display:flex;align-items:center;gap:8px;padding-top:14px;border-top:1px solid rgba(112,74,198,.08)}.book-body strong{font-size:22px;color:var(--el-color-primary)}.book-body small{color:var(--el-text-color-secondary)}.book-body .el-icon{margin-left:auto;color:var(--el-color-primary)}
.hot-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.hot-summary>div{display:flex;flex-direction:column;gap:5px;padding:17px 20px;border:1px solid rgba(112,74,198,.13);border-radius:18px;background:#fff;box-shadow:0 12px 30px rgba(79,51,133,.05)}.hot-summary span,.hot-summary small,.hot-updated{color:var(--el-text-color-secondary)}.hot-summary strong{font-family:Georgia,'Times New Roman',serif;font-size:30px;color:var(--el-color-primary)}.hot-filter-card{margin-bottom:18px;border:1px solid rgba(112,74,198,.13);border-radius:18px;background:linear-gradient(145deg,rgba(255,255,255,.96),rgba(249,247,255,.9))}.hot-filter-card :deep(.el-card__body){padding:18px 20px}.hot-filter-heading,.hot-filter-row{display:flex;justify-content:space-between;align-items:center;gap:14px}.hot-filter-heading h2{margin:5px 0 0;font-size:20px}.hot-filter-row{margin-top:16px}.hot-filter-row .el-select{width:150px}.tag-group{display:flex;gap:7px}.hot-topic-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.hot-topic-card{padding:20px;border:1px solid rgba(112,74,198,.15);border-radius:20px;background:linear-gradient(145deg,#fff,#faf8ff);box-shadow:0 14px 35px rgba(79,51,133,.06);transition:transform .2s,border-color .2s}.hot-topic-card:hover{transform:translateY(-3px);border-color:rgba(112,74,198,.35)}.hot-topic-card h2{margin:15px 0 8px;font-size:20px}.hot-topic-card p{min-height:48px;margin:0 0 16px;color:var(--el-text-color-secondary);line-height:1.7}.hot-evidence{display:flex;justify-content:space-between;gap:10px;padding:11px 12px;margin-bottom:14px;border-radius:10px;background:rgba(112,74,198,.055);font-size:12px;color:var(--el-text-color-secondary)}
@media(max-width:1000px){.stats-row,.hot-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.book-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){.page-header,.filter-row,.form-actions,.hot-filter-heading,.hot-filter-row{flex-direction:column;align-items:stretch}.header-actions{padding-top:0}.filter-row .el-select,.hot-filter-row .el-select{width:100%}.signal-grid,.inspiration-grid,.book-grid,.hot-topic-grid{grid-template-columns:1fr}.hot-summary{grid-template-columns:1fr 1fr}.hot-summary>div{padding:14px}.hot-filter-row :deep(.el-radio-group){display:flex}.hot-filter-row :deep(.el-radio-button){flex:1}.hot-filter-row :deep(.el-radio-button__inner){width:100%;padding-left:8px;padding-right:8px}}
</style>
